CREATE TABLE "users" (
  "user_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "last_name" varchar(50),
  "first_name" varchar(50),
  "email" varchar(254) UNIQUE NOT NULL,
  "password_hash" text,
  "role_id" integer NOT NULL,
  "created_at" timestamptz NOT NULL DEFAULT (now()),
  "deleted_at" timestamptz,
  "must_change_password" bool NOT NULL
);

CREATE TABLE "role" (
  "role_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "role" varchar(50) UNIQUE NOT NULL
);

CREATE TABLE "class" (
  "class_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "class_title" varchar(75) NOT NULL,
  "created_by" integer NOT NULL
);

CREATE TABLE "users_class" (
  "class_id" integer NOT NULL,
  "user_id" integer NOT NULL,
  PRIMARY KEY ("class_id", "user_id")
);

CREATE TABLE "module" (
  "module_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "module_title" varchar(200) NOT NULL,
  "description" text,
  "created_by" integer NOT NULL
);

CREATE TABLE "module_class" (
  "class_id" integer NOT NULL,
  "module_id" integer NOT NULL,
  PRIMARY KEY ("class_id", "module_id")
);

CREATE TABLE "lessons" (
  "lesson_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "lesson_title" varchar(200) NOT NULL,
  "lesson_content" text,
  "module_id" integer NOT NULL
);

CREATE TABLE "lesson_progression" (
  "user_id" integer NOT NULL,
  "lesson_id" integer NOT NULL,
  "completed_on" timestamptz NOT NULL DEFAULT (now()),
  PRIMARY KEY ("user_id", "lesson_id")
);

CREATE TABLE "date_available" (
  "class_id" integer NOT NULL,
  "lesson_id" integer NOT NULL,
  "date_available" timestamptz NOT NULL,
  "date_expiration" timestamptz,
  PRIMARY KEY ("class_id", "lesson_id")
);

CREATE TABLE "media" (
  "media_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "media_url" text NOT NULL,
  "type" varchar(20),
  "lesson_id" integer NOT NULL
);

CREATE TABLE "exams" (
  "exam_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "exam_title" varchar(200) NOT NULL,
  "description" text,
  "threshold" integer NOT NULL CHECK (threshold BETWEEN 0 AND 100),
  "lesson_id" integer UNIQUE NOT NULL
);

CREATE TABLE "mcq_questions" (
  "question_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "exam_id" integer NOT NULL,
  "question_descr" text NOT NULL
);

CREATE TABLE "mcq_choices" (
  "choice_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "question_id" integer NOT NULL,
  "choice_descr" text NOT NULL,
  "is_correct" bool NOT NULL,
  "choice" varchar(2)
);

CREATE TABLE "result_exam" (
  "result_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "result" integer NOT NULL CHECK (result BETWEEN 0 AND 100),
  "created_at" timestamptz NOT NULL DEFAULT (now()),
  "exam_id" integer NOT NULL,
  "user_id" integer NOT NULL
);

CREATE TABLE "sessions" (
  "session_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "tokens" text NOT NULL,
  "created_at" timestamptz NOT NULL DEFAULT (now()),
  "expire_at" timestamptz NOT NULL,
  "user_id" integer NOT NULL
);

CREATE TABLE "login_log" (
  "login_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "user_id" integer NOT NULL,
  "connected" bool NOT NULL,
  "login_at" timestamptz NOT NULL DEFAULT (now())
);

ALTER TABLE "class" ADD FOREIGN KEY ("created_by") REFERENCES "users" ("user_id") ON DELETE RESTRICT DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "users" ADD FOREIGN KEY ("role_id") REFERENCES "role" ("role_id") ON DELETE RESTRICT DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "module" ADD FOREIGN KEY ("created_by") REFERENCES "users" ("user_id") ON DELETE RESTRICT DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "module_class" ADD FOREIGN KEY ("class_id") REFERENCES "class" ("class_id") ON DELETE CASCADE DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "module_class" ADD FOREIGN KEY ("module_id") REFERENCES "module" ("module_id") ON DELETE CASCADE DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "users_class" ADD FOREIGN KEY ("class_id") REFERENCES "class" ("class_id") ON DELETE CASCADE DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "users_class" ADD FOREIGN KEY ("user_id") REFERENCES "users" ("user_id") ON DELETE CASCADE DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "lessons" ADD FOREIGN KEY ("module_id") REFERENCES "module" ("module_id") ON DELETE CASCADE DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "exams" ADD FOREIGN KEY ("lesson_id") REFERENCES "lessons" ("lesson_id") ON DELETE CASCADE DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "mcq_questions" ADD FOREIGN KEY ("exam_id") REFERENCES "exams" ("exam_id") ON DELETE CASCADE DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "mcq_choices" ADD FOREIGN KEY ("question_id") REFERENCES "mcq_questions" ("question_id") ON DELETE CASCADE DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "date_available" ADD FOREIGN KEY ("class_id") REFERENCES "class" ("class_id") ON DELETE CASCADE DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "date_available" ADD FOREIGN KEY ("lesson_id") REFERENCES "lessons" ("lesson_id") ON DELETE CASCADE DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "media" ADD FOREIGN KEY ("lesson_id") REFERENCES "lessons" ("lesson_id") ON DELETE CASCADE DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "result_exam" ADD FOREIGN KEY ("exam_id") REFERENCES "exams" ("exam_id") ON DELETE RESTRICT DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "result_exam" ADD FOREIGN KEY ("user_id") REFERENCES "users" ("user_id") ON DELETE RESTRICT DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "sessions" ADD FOREIGN KEY ("user_id") REFERENCES "users" ("user_id") ON DELETE CASCADE DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "lesson_progression" ADD FOREIGN KEY ("user_id") REFERENCES "users" ("user_id") ON DELETE CASCADE DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "lesson_progression" ADD FOREIGN KEY ("lesson_id") REFERENCES "lessons" ("lesson_id") ON DELETE CASCADE DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "login_log" ADD FOREIGN KEY ("user_id") REFERENCES "users" ("user_id") ON DELETE RESTRICT DEFERRABLE INITIALLY IMMEDIATE;
